export function formatNumber(value, locale) {
    return new Intl.NumberFormat(locale, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(value);
}
export const SUPPORTED_CURRENCIES = ["EUR", "USD", "GBP"];
const currencyAliases = {
    "€": "EUR",
    "$": "USD",
    "£": "GBP"
};
export function normalizeCurrency(currency) {
    const normalized = currency.trim();
    const currencyCode = currencyAliases[normalized] || normalized.toUpperCase();
    return SUPPORTED_CURRENCIES.includes(currencyCode)
        ? currencyCode
        : null;
}
export function formatCurrency(value, currency, locale) {
    const currencyCode = normalizeCurrency(currency);
    if (!currencyCode) {
        return "—";
    }
    return new Intl.NumberFormat(locale, {
        style: "currency",
        currency: currencyCode,
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(value);
}
export function getCurrencySymbol(currency, locale) {
    const currencyCode = normalizeCurrency(currency);
    if (!currencyCode)
        return currency;
    return new Intl.NumberFormat(locale, {
        style: "currency",
        currency: currencyCode,
        currencyDisplay: "narrowSymbol"
    }).formatToParts(0).find((part) => part.type === "currency")?.value || currencyCode;
}
export function formatPercentage(value, locale) {
    return new Intl.NumberFormat(locale, {
        style: "percent",
        maximumFractionDigits: 1,
        minimumFractionDigits: value % 1 === 0 ? 0 : 1,
        signDisplay: value === 0 ? "never" : "always"
    }).format(value / 100);
}
