import { formatDateParam } from "../../../utils/date";
export function getDatedDownloadFilename(response, date = new Date(), fallbackFilename = "receipts.zip") {
    const disposition = response.headers.get("Content-Disposition");
    const dispositionMatch = disposition?.match(/filename="?([^";]+)"?/i);
    const originalFilename = dispositionMatch?.[1] || fallbackFilename;
    const formattedDate = formatDateParam(date);
    const extensionIndex = originalFilename.lastIndexOf(".");
    return extensionIndex > 0
        ? `${originalFilename.slice(0, extensionIndex)}-${formattedDate}${originalFilename.slice(extensionIndex)}`
        : `${originalFilename}-${formattedDate}`;
}
