import { format, parseISO, startOfMonth } from "date-fns";
import { toZonedTime } from "date-fns-tz";
import { enGB } from "date-fns/locale/en-GB";
import { enUS } from "date-fns/locale/en-US";
import { es } from "date-fns/locale/es";
import { ru } from "date-fns/locale/ru";
export function getDateFnsLocale(locale) {
    const normalizedLocale = locale.toLowerCase();
    if (normalizedLocale.startsWith("ru"))
        return ru;
    if (normalizedLocale.startsWith("es"))
        return es;
    return normalizedLocale === "en-us" ? enUS : enGB;
}
export function getDatePickerFormat(locale, numeric = false) {
    if (locale.toLowerCase().startsWith("ru"))
        return numeric ? "dd.MM.yyyy" : "d MMM yyyy";
    const parts = new Intl.DateTimeFormat(locale, {
        day: numeric ? "2-digit" : "numeric",
        month: numeric ? "2-digit" : "short",
        year: "numeric"
    }).formatToParts(new Date(Date.UTC(2006, 10, 22)));
    return parts.map((part) => {
        if (part.type === "day")
            return numeric ? "dd" : "d";
        if (part.type === "month")
            return numeric ? "MM" : "MMM";
        if (part.type === "year")
            return "yyyy";
        return part.value.replace(/[\u200e\u200f]/g, "");
    }).join("");
}
export function dateFromParam(value) {
    return value ? parseISO(value) : undefined;
}
export function formatDateParam(date) {
    return format(date, "yyyy-MM-dd");
}
export function getCurrentMonthStart(today = new Date()) {
    return startOfMonth(today);
}
export function formatDate(isoString, locale) {
    const date = new Date(isoString);
    return date.toLocaleString(locale, {
        weekday: "short",
        day: "numeric",
        month: "long",
        year: "numeric"
    });
}
export function formatTime(isoString) {
    const utcDate = toZonedTime(isoString, "UTC");
    const result = format(utcDate, "HH:mm");
    return result === "00:00" ? "" : result;
}
function formatDateWithoutTrailingYearLabel(formatter, date) {
    const parts = formatter.formatToParts(date);
    const yearIndex = parts.findLastIndex((part) => part.type === "year");
    return parts
        .filter((part, index) => index <= yearIndex || part.type !== "literal")
        .map((part) => part.value)
        .join("");
}
export function formatReceiptDate(dateValue, locale) {
    const date = new Date(dateValue);
    const datePart = formatDateWithoutTrailingYearLabel(new Intl.DateTimeFormat(locale, {
        day: "numeric",
        month: "short",
        year: "numeric",
        timeZone: "UTC"
    }), date);
    const timePart = new Intl.DateTimeFormat(locale, {
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
        timeZone: "UTC"
    }).format(date);
    return { datePart, timePart: timePart === "00:00" ? "" : timePart };
}
export function formatReceiptDateTime(dateValue, locale) {
    const date = new Date(dateValue);
    if (Number.isNaN(date.getTime()))
        return "—";
    const datePart = formatDateWithoutTrailingYearLabel(new Intl.DateTimeFormat(locale, {
        day: "numeric",
        month: "long",
        year: "numeric",
        timeZone: "UTC"
    }), date);
    const timePart = new Intl.DateTimeFormat(locale, {
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
        timeZone: "UTC"
    }).format(date);
    return `${datePart}, ${timePart}`;
}
