import { useCallback, useEffect, useRef, useState } from "react";
import { EMPTY_SHOPPING_LIST_DRAFT, createShoppingListId, loadShoppingListDraft, orderShoppingListItems, saveShoppingListDraft } from "../../utils/shoppingLists";
import { toShoppingListItemInput } from "../../utils/toShoppingListItemInput";
import useShoppingListsCache from "../useShoppingListsCache";
import useShoppingListsMutations from "../useShoppingListsMutations";
import useShoppingListsQuery from "../useShoppingListsQuery";
export default function useShoppingListsController() {
    const initialDraft = useRef(loadShoppingListDraft());
    const [draft, setDraft] = useState(initialDraft.current.data);
    const [hasStorageError, setHasStorageError] = useState(initialDraft.current.hasError);
    const [mutationError, setMutationError] = useState(null);
    const isInitialRender = useRef(true);
    const shoppingListsQuery = useShoppingListsQuery();
    const { createMutation, updateMutation, deleteMutation } = useShoppingListsMutations();
    const { getList, replaceList, removeList } = useShoppingListsCache();
    useEffect(() => {
        if (isInitialRender.current) {
            isInitialRender.current = false;
            return;
        }
        setHasStorageError(!saveShoppingListDraft(draft));
    }, [draft]);
    const retry = useCallback(() => {
        void shoppingListsQuery.refetch();
    }, [shoppingListsQuery]);
    const dismissStorageError = useCallback(() => setHasStorageError(false), []);
    const dismissMutationError = useCallback(() => setMutationError(null), []);
    const updateDraftName = useCallback((name) => {
        setDraft((current) => ({ ...current, name }));
    }, []);
    const addDraftItem = useCallback((name) => {
        setDraft((current) => ({
            ...current,
            items: [
                ...current.items,
                { id: createShoppingListId(), name, isCompleted: false }
            ]
        }));
    }, []);
    const toggleDraftItem = useCallback((id) => {
        setDraft((current) => ({
            ...current,
            items: current.items.map((item) => (item.id === id ? { ...item, isCompleted: !item.isCompleted } : item))
        }));
    }, []);
    const removeDraftItem = useCallback((id) => {
        setDraft((current) => ({
            ...current,
            items: current.items.filter((item) => item.id !== id)
        }));
    }, []);
    const reorderDraftItems = useCallback((orderedIds) => {
        setDraft((current) => {
            const items = orderShoppingListItems(current.items, orderedIds);
            return items === current.items ? current : { ...current, items };
        });
    }, []);
    const clearDraft = useCallback(() => {
        setDraft(EMPTY_SHOPPING_LIST_DRAFT);
        setHasStorageError(!saveShoppingListDraft(EMPTY_SHOPPING_LIST_DRAFT));
    }, []);
    const saveDraft = useCallback(async () => {
        const name = draft.name.trim();
        if (!name || createMutation.isPending)
            return null;
        setMutationError(null);
        try {
            const shoppingList = await createMutation.mutateAsync({
                name,
                items: draft.items.map(({ name: itemName, isCompleted }) => ({
                    name: itemName,
                    isCompleted
                }))
            });
            replaceList(shoppingList);
            clearDraft();
            return shoppingList.id;
        }
        catch {
            setMutationError("save");
            return null;
        }
    }, [clearDraft, createMutation, draft, replaceList]);
    const updateCachedList = useCallback(async (id, createInput) => {
        if (updateMutation.isPending)
            return false;
        const list = getList(id);
        if (!list)
            return false;
        setMutationError(null);
        try {
            const shoppingList = await updateMutation.mutateAsync({ id, data: createInput(list) });
            replaceList(shoppingList);
            return true;
        }
        catch {
            setMutationError("update");
            return false;
        }
    }, [getList, replaceList, updateMutation]);
    const renameList = useCallback(async (id, rawName) => {
        const name = rawName.trim();
        if (!name)
            return false;
        const list = getList(id);
        if (list?.name === name)
            return true;
        return updateCachedList(id, (current) => ({
            name,
            items: current.items.map(toShoppingListItemInput)
        }));
    }, [getList, updateCachedList]);
    const addListItem = useCallback((listId, name) => (updateCachedList(listId, (list) => ({
        name: list.name,
        items: [
            ...list.items.map(toShoppingListItemInput),
            { name, isCompleted: false }
        ]
    }))), [updateCachedList]);
    const toggleListItem = useCallback((listId, itemId) => (updateCachedList(listId, (list) => ({
        name: list.name,
        items: list.items.map((item) => ({
            ...toShoppingListItemInput(item),
            isCompleted: item.id === itemId ? !item.isCompleted : item.isCompleted
        }))
    }))), [updateCachedList]);
    const removeListItem = useCallback((listId, itemId) => (updateCachedList(listId, (list) => ({
        name: list.name,
        items: list.items.filter((item) => item.id !== itemId).map(toShoppingListItemInput)
    }))), [updateCachedList]);
    const reorderListItems = useCallback(async (listId, orderedIds) => {
        if (updateMutation.isPending)
            return false;
        const list = getList(listId);
        if (!list)
            return false;
        const items = orderShoppingListItems(list.items, orderedIds);
        if (items === list.items)
            return true;
        const optimisticList = { ...list, items };
        setMutationError(null);
        replaceList(optimisticList);
        try {
            const shoppingList = await updateMutation.mutateAsync({
                id: listId,
                data: {
                    name: list.name,
                    items: items.map(toShoppingListItemInput)
                }
            });
            replaceList(shoppingList);
            return true;
        }
        catch {
            replaceList(list);
            setMutationError("update");
            return false;
        }
    }, [getList, replaceList, updateMutation]);
    const deleteList = useCallback(async (id) => {
        if (deleteMutation.isPending)
            return false;
        try {
            await deleteMutation.mutateAsync(id);
            removeList(id);
            return true;
        }
        catch {
            return false;
        }
    }, [deleteMutation, removeList]);
    return {
        lists: shoppingListsQuery.data || [],
        draft,
        isLoading: shoppingListsQuery.isPending,
        isFetching: shoppingListsQuery.isFetching,
        hasLoadError: shoppingListsQuery.isLoadingError,
        hasStorageError,
        mutationError,
        isCreating: createMutation.isPending,
        isUpdating: updateMutation.isPending,
        isDeleting: deleteMutation.isPending,
        retry,
        dismissStorageError,
        dismissMutationError,
        updateDraftName,
        addDraftItem,
        toggleDraftItem,
        removeDraftItem,
        reorderDraftItems,
        clearDraft,
        saveDraft,
        renameList,
        addListItem,
        toggleListItem,
        removeListItem,
        reorderListItems,
        deleteList
    };
}
