import { useCallback, useState } from "react";
import { deleteReceiptRequest } from "../../api";
export default function useReceiptDeletion({ onDeleted, receiptId }) {
    const [isDeleteOpen, setIsDeleteOpen] = useState(false);
    const [isDeleting, setIsDeleting] = useState(false);
    const [hasDeleteError, setHasDeleteError] = useState(false);
    const confirmDelete = useCallback(async () => {
        if (!receiptId || isDeleting)
            return;
        setIsDeleting(true);
        setHasDeleteError(false);
        try {
            const response = await deleteReceiptRequest(receiptId);
            if (!response.ok)
                throw new Error("Failed to delete receipt");
            setIsDeleteOpen(false);
            onDeleted(receiptId);
        }
        catch (error) {
            console.error(error);
            setHasDeleteError(true);
        }
        finally {
            setIsDeleting(false);
        }
    }, [isDeleting, onDeleted, receiptId]);
    const closeDeleteDialog = useCallback(() => {
        setIsDeleteOpen(false);
        setHasDeleteError(false);
    }, []);
    const openDeleteDialog = useCallback(() => setIsDeleteOpen(true), []);
    return {
        closeDeleteDialog,
        confirmDelete,
        hasDeleteError,
        isDeleteOpen,
        isDeleting,
        openDeleteDialog
    };
}
