import { useCallback, useRef, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../../../auth";
export default function useReceiptNavigationGuard({ isDirty, onDiscard }) {
    const { logout } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();
    const [isDiscardOpen, setIsDiscardOpen] = useState(false);
    const pendingActionRef = useRef(null);
    const navigateToReceipts = useCallback((notification) => {
        navigate({ pathname: "/receipts", search: location.search }, {
            state: {
                scrollTop: location.state?.scrollTop,
                notification
            }
        });
    }, [location.search, location.state?.scrollTop, navigate]);
    const requestAction = useCallback((action) => {
        if (isDirty) {
            pendingActionRef.current = action;
            setIsDiscardOpen(true);
            return;
        }
        action();
    }, [isDirty]);
    const handleBreadcrumb = useCallback((event) => {
        event.preventDefault();
        requestAction(() => navigateToReceipts());
    }, [navigateToReceipts, requestAction]);
    const cancelEdit = useCallback(() => {
        if (isDirty) {
            pendingActionRef.current = null;
            setIsDiscardOpen(true);
            return;
        }
        onDiscard();
    }, [isDirty, onDiscard]);
    const confirmDiscard = useCallback(() => {
        const action = pendingActionRef.current;
        pendingActionRef.current = null;
        setIsDiscardOpen(false);
        onDiscard();
        action?.();
    }, [onDiscard]);
    const cancelDiscard = useCallback(() => {
        pendingActionRef.current = null;
        setIsDiscardOpen(false);
    }, []);
    const handleSidebarNavigate = useCallback((to) => {
        requestAction(() => {
            if (to === "/receipts") {
                navigateToReceipts();
                return;
            }
            navigate(to);
        });
    }, [navigate, navigateToReceipts, requestAction]);
    const handleLogout = useCallback(() => requestAction(logout), [logout, requestAction]);
    return {
        backTo: `/receipts${location.search}`,
        cancelDiscard,
        cancelEdit,
        confirmDiscard,
        handleBreadcrumb,
        handleLogout,
        handleSidebarNavigate,
        isDiscardOpen,
        navigateToReceipts
    };
}
