import { useCallback, useEffect, useState } from "react";
import { fetchReceiptImageRequest } from "../../api";
import { getReceiptFileName } from "../../utils/receiptImage";
export default function useReceiptImageFile(receipt) {
    const [file, setFile] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const [hasError, setHasError] = useState(false);
    const [retryKey, setRetryKey] = useState(0);
    useEffect(() => {
        const imageId = receipt.receiptImageId;
        if (!imageId) {
            setFile(null);
            setHasError(false);
            setIsLoading(false);
            return;
        }
        const controller = new AbortController();
        let objectUrl = "";
        async function loadImage(receiptImageId) {
            setIsLoading(true);
            setHasError(false);
            try {
                const response = await fetchReceiptImageRequest(receiptImageId, controller.signal);
                if (!response.ok)
                    throw new Error("Failed to load receipt file");
                const blob = await response.blob();
                if (controller.signal.aborted)
                    return;
                objectUrl = URL.createObjectURL(blob);
                setFile({
                    url: objectUrl,
                    size: blob.size,
                    name: getReceiptFileName(receipt.date, blob.type),
                    isImage: blob.type.startsWith("image/")
                });
            }
            catch (loadError) {
                if (!controller.signal.aborted) {
                    console.error(loadError);
                    setFile(null);
                    setHasError(true);
                }
            }
            finally {
                if (!controller.signal.aborted)
                    setIsLoading(false);
            }
        }
        void loadImage(imageId);
        return () => {
            controller.abort();
            if (objectUrl)
                URL.revokeObjectURL(objectUrl);
        };
    }, [receipt.date, receipt.receiptImageId, retryKey]);
    const retry = useCallback(() => setRetryKey((value) => value + 1), []);
    return { file, hasError, isLoading, retry };
}
