import { useCallback, useState } from "react";
import { downloadReceiptsRequest } from "../../api";
import { getDatedDownloadFilename } from "../../utils/download";
export default function useReceiptExport() {
    const [isDownloading, setIsDownloading] = useState(false);
    const [hasDownloadError, setHasDownloadError] = useState(false);
    const downloadReceipts = useCallback(async () => {
        setIsDownloading(true);
        setHasDownloadError(false);
        try {
            const response = await downloadReceiptsRequest();
            if (!response.ok)
                throw new Error("Failed to download receipts");
            const url = window.URL.createObjectURL(await response.blob());
            const anchor = document.createElement("a");
            anchor.href = url;
            anchor.download = getDatedDownloadFilename(response);
            document.body.appendChild(anchor);
            anchor.click();
            anchor.remove();
            window.URL.revokeObjectURL(url);
        }
        catch (error) {
            console.error("Download error:", error);
            setHasDownloadError(true);
        }
        finally {
            setIsDownloading(false);
        }
    }, []);
    return { downloadReceipts, hasDownloadError, isDownloading };
}
