import { TOKEN_NAME } from "../../../constants";
import Storage from "../../../utils/Storage";
import { isDeleteShoppingListResponse, isShoppingList, isShoppingListArray } from "../utils/shoppingLists";
const SERVER_URL = process.env.NODE_ENV === "production"
    ? process.env.SERVER_URL_PROD
    : process.env.SERVER_URL_DEV;
function authenticatedHeaders(includeContentType = false) {
    return {
        "Authorization": `Bearer ${Storage.get(TOKEN_NAME)}`,
        ...(includeContentType ? { "Content-Type": "application/json" } : {})
    };
}
export async function loadShoppingLists(signal) {
    try {
        const response = await fetch(`${SERVER_URL}/api/get-shopping-lists`, {
            signal,
            headers: authenticatedHeaders()
        });
        const data = await response.json();
        if (!response.ok || !isShoppingListArray(data)) {
            throw new Error("Invalid shopping-list response");
        }
        return data;
    }
    catch (error) {
        console.error("Failed to load shopping lists:", error);
        throw error;
    }
}
export async function createShoppingList(data) {
    try {
        const response = await fetch(`${SERVER_URL}/api/save-shopping-list`, {
            method: "POST",
            body: JSON.stringify(data),
            headers: authenticatedHeaders(true)
        });
        const shoppingList = await response.json();
        if (!response.ok || !isShoppingList(shoppingList)) {
            throw new Error("Invalid saved shopping-list response");
        }
        return shoppingList;
    }
    catch (error) {
        console.error("Failed to save shopping list:", error);
        throw error;
    }
}
export async function updateShoppingList(id, data) {
    try {
        const response = await fetch(`${SERVER_URL}/api/update-shopping-list/${id}`, {
            method: "PUT",
            body: JSON.stringify(data),
            headers: authenticatedHeaders(true)
        });
        const shoppingList = await response.json();
        if (!response.ok || !isShoppingList(shoppingList)) {
            throw new Error("Invalid updated shopping-list response");
        }
        return shoppingList;
    }
    catch (error) {
        console.error("Failed to update shopping list:", error);
        throw error;
    }
}
export async function removeShoppingList(id) {
    try {
        const response = await fetch(`${SERVER_URL}/api/delete-shopping-list/${id}`, {
            method: "DELETE",
            headers: authenticatedHeaders()
        });
        const result = await response.json();
        if (!response.ok || !isDeleteShoppingListResponse(result)) {
            throw new Error("Invalid delete shopping-list response");
        }
    }
    catch (error) {
        console.error("Failed to delete shopping list:", error);
        throw error;
    }
}
